public int getRegionId(BlockPos pos) {
        int id = -1;
        for (int[] neighbour : neighbours) {
            int x = pos.getX() + neighbour[0] * CHUNK_SIZE;
            int z = pos.getZ() + neighbour[1] * CHUNK_SIZE;
            long rid = toId(x, z);
            if (map.containsKey(rid)) {
                id = map.get(rid);
                break;
            }
        }
        if (id == -1) {
            id = random.nextInt();
        }

        long rid = toId(pos.getX(), pos.getZ());
        if (!map.containsKey(rid)) {
            map.put(rid, id);
            markDirty();
        }
        return id;
    }

